const jwt = global.get('jwt');
const secret = global.get('JWT_SECRET');

const header = msg.req?.headers?.authorization || "";
const token = header.startsWith("Bearer ") ? header.slice(7) : null;

if (!token) {
    msg.statusCode = 401;
    msg.payload = { hata: "Token yok." };
    return [null, msg];
}

