    const veri = jwt.verify(token, secret);

    msg.kullaniciId = veri.sub;
    msg.rol         = veri.rol || "kullanici";
    msg.adminMi     = msg.rol === "admin";

    return [msg, null];
} catch (e) {
    msg.statusCode = 401;
    msg.payload = { hata: "Token geçersiz veya süresi dolmuş." };
